/* ============================================================
   Cozy City Time Machine — Styles
   Warm, cozy, miniature-diorama aesthetic.
   ============================================================ */

:root {
  --bg-1: #2a1c36;
  --bg-2: #4a2f4f;
  --warm: #ffcf9e;
  --warm-deep: #f5a661;
  --cream: #fff4e6;
  --pink: #ffb3c8;
  --teal: #7ecfb3;
  --shadow: rgba(30, 16, 40, 0.35);
  --panel: rgba(255, 244, 230, 0.94);
  --panel-edge: rgba(255, 255, 255, 0.7);
  font-size: 16px;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

html, body {
  width: 100%;
  height: 100%;
  overflow: hidden;
  font-family: "Segoe UI", "Nunito", system-ui, -apple-system, sans-serif;
  background: radial-gradient(circle at 50% 20%, var(--bg-1), var(--bg-2) 70%, #1a1226);
  color: var(--cream);
  -webkit-font-smoothing: antialiased;
  user-select: none;
}

#app {
  position: fixed;
  inset: 0;
  display: block;
}

canvas { display: block; cursor: grab; }
canvas:active { cursor: grabbing; }

/* ---------- Overlay / Start ---------- */
.overlay {
  position: fixed;
  inset: 0;
  z-index: 100;
  display: flex;
  align-items: center;
  justify-content: center;
  background: radial-gradient(circle at 50% 40%, rgba(120, 80, 150, 0.55), rgba(26, 18, 38, 0.92));
  backdrop-filter: blur(6px);
  transition: opacity 0.8s ease;
}
.overlay.hidden { opacity: 0; pointer-events: none; }

.start-card {
  text-align: center;
  padding: 48px 56px;
  border-radius: 28px;
  background: linear-gradient(160deg, var(--panel), #ffe8d3);
  color: #4a2f4f;
  box-shadow: 0 24px 60px rgba(0,0,0,0.45), inset 0 1px 0 rgba(255,255,255,0.8);
  transform: translateY(0);
  animation: floaty 4s ease-in-out infinite;
  max-width: 90vw;
}
@keyframes floaty { 0%,100%{ transform: translateY(0);} 50%{ transform: translateY(-10px);} }

.start-title {
  font-size: 2.6rem;
  font-weight: 800;
  letter-spacing: -0.5px;
  background: linear-gradient(90deg, #e0677e, #f5a661, #7ecfb3);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  margin-bottom: 8px;
}
.start-sub { font-size: 1.05rem; opacity: 0.75; margin-bottom: 28px; font-weight: 500; }

.btn-primary {
  font-size: 1.1rem;
  font-weight: 700;
  color: #fff;
  background: linear-gradient(135deg, var(--warm-deep), #ff8fab);
  border: none;
  padding: 15px 38px;
  border-radius: 999px;
  cursor: pointer;
  box-shadow: 0 10px 24px rgba(245, 166, 97, 0.45);
  transition: transform 0.15s ease, box-shadow 0.15s ease;
}
.btn-primary:hover { transform: translateY(-2px) scale(1.03); box-shadow: 0 14px 30px rgba(245, 166, 97, 0.55); }
.btn-primary:active { transform: translateY(0) scale(0.99); }

.start-hint { margin-top: 24px; font-size: 0.82rem; opacity: 0.6; }

/* ---------- HUD ---------- */
.hud {
  position: fixed;
  top: 0; left: 0; right: 0;
  z-index: 50;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 20px;
  background: linear-gradient(180deg, rgba(26,18,38,0.65), rgba(26,18,38,0));
  pointer-events: none;
}
.hud.hidden { display: none; }
.hud-left, .hud-right { display: flex; align-items: center; gap: 12px; pointer-events: auto; }
.logo { font-weight: 800; font-size: 1.1rem; letter-spacing: 0.3px; text-shadow: 0 2px 8px rgba(0,0,0,0.5); }

.time-badge {
  font-size: 0.8rem;
  padding: 6px 14px;
  border-radius: 999px;
  background: rgba(255, 207, 158, 0.18);
  border: 1px solid rgba(255, 207, 158, 0.4);
  color: var(--warm);
  backdrop-filter: blur(6px);
  font-weight: 600;
}

.control-group { display: flex; gap: 8px; }

.ctrl-btn {
  display: flex;
  align-items: center;
  gap: 7px;
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--cream);
  background: rgba(255, 244, 230, 0.1);
  border: 1px solid rgba(255, 244, 230, 0.22);
  padding: 9px 14px;
  border-radius: 14px;
  cursor: pointer;
  backdrop-filter: blur(8px);
  transition: all 0.18s ease;
}
.ctrl-btn:hover { background: rgba(255, 244, 230, 0.2); transform: translateY(-1px); }
.ctrl-btn.active {
  background: linear-gradient(135deg, rgba(255,207,158,0.35), rgba(255,143,171,0.35));
  border-color: rgba(255, 207, 158, 0.6);
  box-shadow: 0 0 16px rgba(255, 207, 158, 0.3);
}
.ctrl-btn .icon { font-size: 1rem; }

/* ---------- Info card ---------- */
.info-card {
  position: fixed;
  left: 20px;
  bottom: 20px;
  z-index: 60;
  width: 300px;
  max-width: calc(100vw - 40px);
  padding: 20px 22px 18px;
  background: var(--panel);
  color: #4a2f4f;
  border-radius: 22px;
  box-shadow: 0 18px 44px rgba(0,0,0,0.4), inset 0 1px 0 #fff;
  animation: pop 0.35s cubic-bezier(0.34, 1.56, 0.64, 1);
}
.info-card.hidden { display: none; }
@keyframes pop { from { transform: translateY(20px) scale(0.94); opacity: 0; } }

.info-close {
  position: absolute;
  top: 12px; right: 14px;
  background: none; border: none;
  font-size: 1.5rem; line-height: 1;
  color: #a0788f;
  cursor: pointer;
}
.info-close:hover { color: #4a2f4f; }

.info-icon { font-size: 2.4rem; margin-bottom: 6px; }
.info-title { font-size: 1.35rem; font-weight: 800; margin-bottom: 6px; color: #5a3a2f; }
.info-desc { font-size: 0.92rem; line-height: 1.5; color: #6d5467; }

/* ---------- Legend ---------- */
.legend {
  position: fixed;
  right: 20px;
  bottom: 20px;
  z-index: 40;
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 14px 16px;
  background: rgba(26, 18, 38, 0.5);
  border: 1px solid rgba(255, 244, 230, 0.15);
  border-radius: 16px;
  backdrop-filter: blur(8px);
  font-size: 0.78rem;
  color: rgba(255, 244, 230, 0.8);
}
.legend.hidden { display: none; }
.legend-item { display: flex; align-items: center; gap: 10px; }
.kbd {
  display: inline-block;
  min-width: 44px;
  text-align: center;
  padding: 3px 8px;
  border-radius: 7px;
  background: rgba(255,244,230,0.12);
  border: 1px solid rgba(255,244,230,0.25);
  color: var(--warm);
  font-weight: 600;
  font-size: 0.72rem;
}

/* ---------- Loader ---------- */
.loader {
  position: fixed;
  inset: 0;
  z-index: 200;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 18px;
  background: radial-gradient(circle at 50% 40%, var(--bg-1), #1a1226);
  color: var(--warm);
  font-weight: 600;
}
.loader.hidden { display: none; }
.spinner {
  width: 44px; height: 44px;
  border: 4px solid rgba(255, 207, 158, 0.25);
  border-top-color: var(--warm);
  border-radius: 50%;
  animation: spin 0.9s linear infinite;
}
@keyframes spin { to { transform: rotate(360deg); } }

/* Focus ring for accessibility on buttons */
:focus-visible { outline: 3px solid var(--warm); outline-offset: 2px; border-radius: 8px; }

@media (max-width: 640px) {
  .start-title { font-size: 2rem; }
  .start-card { padding: 36px 28px; }
  .ctrl-btn .label { display: none; }
  .info-card { left: 12px; right: 12px; bottom: 12px; width: auto; }
  .legend { display: none !important; }
}

/* ============================================================
