import struct, zlib
with open('diorama_noshadow.png','rb') as f: data=f.read()
i=8; idat=b''
while i<len(data):
    ln=struct.unpack('>I',data[i:i+4])[0]; typ=data[i+4:i+8]
    if typ==b'IDAT': idat+=data[i+8:i+8+ln]
    if typ==b'IHDR': w,h=struct.unpack('>II',data[i+8:i+16])
    i=i+12+ln
    if typ==b'IEND': break
raw=zlib.decompress(idat); bpp=3
def px(x,y):
    o=(y*w+x)*bpp; return tuple(raw[o+i] for i in range(3))
def avg(sx,sy,ex,ey):
    ss=[0,0,0];n=0
    for y in range(sy,ey):
        for x in range(sx,ex):
            p=px(x,y); ss[0]+=p[0];ss[1]+=p[1];ss[2]+=p[2];n+=1
    return [ss[0]//n,ss[1]//n,ss[2]//n]
print('top band:', avg(0,0,w,h//3),'mid:',avg(0,h//3,w,2*h//3))
seen=set()
for y in range(0,h,4):
    for x in range(0,w,4): seen.add(px(x,y))
print('distinct colors:', len(seen))
